From 16ceb560954f2238dcdad73a75d5e5842e58c839 Mon Sep 17 00:00:00 2001
From: Tomasz Stachowiak <h3@h3.gd>
Date: Tue, 20 Aug 2024 00:02:59 +0200
Subject: [PATCH] Add `RawBufferLoad2` with a `uint` param.

Based on https://github.com/chenyong2github/UnrealEngine/commit/a89065b5834e47be9d4803cc599848d5e2a1735b#diff-ab547556dd9e1d325939a0b47746454c51c571339a614dd5121fe63b5a0c8ab3
---
 include/dxc/HlslIntrinsicOp.h          |  3 +++
 lib/HLSL/HLOperationLower.cpp          |  2 ++
 tools/clang/lib/SPIRV/SpirvEmitter.cpp | 20 ++++++++++++++++
 tools/clang/lib/Sema/SemaHLSL.cpp      | 32 +++++++++++++++-----------
 utils/hct/gen_intrin_main.txt          |  2 ++
 5 files changed, 45 insertions(+), 14 deletions(-)

diff --git a/include/dxc/HlslIntrinsicOp.h b/include/dxc/HlslIntrinsicOp.h
index c8ed2cbd2a..85a0bef472 100644
--- a/include/dxc/HlslIntrinsicOp.h
+++ b/include/dxc/HlslIntrinsicOp.h
@@ -229,6 +229,9 @@ enum class IntrinsicOp {
 #ifdef ENABLE_SPIRV_CODEGEN
   IOP_VkRawBufferLoad,
 #endif // ENABLE_SPIRV_CODEGEN
+#ifdef ENABLE_SPIRV_CODEGEN
+  IOP_VkRawBufferLoad2,
+#endif // ENABLE_SPIRV_CODEGEN
 #ifdef ENABLE_SPIRV_CODEGEN
   IOP_VkRawBufferStore,
 #endif // ENABLE_SPIRV_CODEGEN
diff --git a/lib/HLSL/HLOperationLower.cpp b/lib/HLSL/HLOperationLower.cpp
index b07577374f..1b3543d28a 100644
--- a/lib/HLSL/HLOperationLower.cpp
+++ b/lib/HLSL/HLOperationLower.cpp
@@ -6523,6 +6523,8 @@ IntrinsicLower gLowerTable[] = {
 #ifdef ENABLE_SPIRV_CODEGEN
     {IntrinsicOp::IOP_VkRawBufferLoad, UnsupportedVulkanIntrinsic,
      DXIL::OpCode::NumOpCodes},
+    {IntrinsicOp::IOP_VkRawBufferLoad2, UnsupportedVulkanIntrinsic,
+     DXIL::OpCode::NumOpCodes},
     {IntrinsicOp::IOP_VkRawBufferStore, UnsupportedVulkanIntrinsic,
      DXIL::OpCode::NumOpCodes},
     {IntrinsicOp::IOP_VkReadClock, UnsupportedVulkanIntrinsic,
diff --git a/tools/clang/lib/SPIRV/SpirvEmitter.cpp b/tools/clang/lib/SPIRV/SpirvEmitter.cpp
index fd7159b419..ca49a3581f 100644
--- a/tools/clang/lib/SPIRV/SpirvEmitter.cpp
+++ b/tools/clang/lib/SPIRV/SpirvEmitter.cpp
@@ -573,6 +573,18 @@ const StructType *lowerStructType(const SpirvCodeGenOptions &spirvOptions,

 } // namespace

+bool isVkRawBufferLoad2Intrinsic(const clang::FunctionDecl *FD) {
+  if (!FD->getName().equals("RawBufferLoad2"))
+    return false;
+
+  if (auto *nsDecl = dyn_cast<NamespaceDecl>(FD->getDeclContext())) {
+    if (!nsDecl->getName().equals("vk"))
+      return false;
+  }
+
+  return true;
+}
+
 SpirvEmitter::SpirvEmitter(CompilerInstance &ci)
     : theCompilerInstance(ci), astContext(ci.getASTContext()),
       diags(ci.getDiagnostics()),
@@ -2907,6 +2919,11 @@ SpirvInstruction *SpirvEmitter::doCallExpr(const CallExpr *callExpr,
     return processRawBufferLoad(callExpr);
   }

+  // Handle 'vk::RawBufferLoad2()'
+  if (isVkRawBufferLoad2Intrinsic(funcDecl)) {
+    return processRawBufferLoad(callExpr);
+  }
+
   // Normal standalone functions
   return processCall(callExpr);
 }
@@ -8907,6 +8924,9 @@ SpirvEmitter::processIntrinsicCallExpr(const CallExpr *callExpr) {
   case hlsl::IntrinsicOp::IOP_VkRawBufferLoad:
     retVal = processRawBufferLoad(callExpr);
     break;
+  case hlsl::IntrinsicOp::IOP_VkRawBufferLoad2:
+    retVal = processRawBufferLoad(callExpr);
+    break;
   case hlsl::IntrinsicOp::IOP_VkRawBufferStore:
     retVal = processRawBufferStore(callExpr);
     break;
diff --git a/tools/clang/lib/Sema/SemaHLSL.cpp b/tools/clang/lib/Sema/SemaHLSL.cpp
index 0d05c6825f..6b69ed47bf 100644
--- a/tools/clang/lib/Sema/SemaHLSL.cpp
+++ b/tools/clang/lib/Sema/SemaHLSL.cpp
@@ -300,8 +300,8 @@ enum ArBasicKind {
 #define BPROP_BITS64 0x00000006
 #define BPROP_BITS_NON_PRIM 0x00000007

-#define GET_BPROP_SUBTYPE(_Props) ((_Props)&BPROP_SUBTYPE_MASK)
-#define GET_BPROP_BITS(_Props) ((_Props)&BPROP_SUBTYPE_MASK)
+#define GET_BPROP_SUBTYPE(_Props) ((_Props) & BPROP_SUBTYPE_MASK)
+#define GET_BPROP_BITS(_Props) ((_Props) & BPROP_SUBTYPE_MASK)

 #define BPROP_BOOLEAN 0x00000010 // Whether the type is bool
 #define BPROP_INTEGER 0x00000020 // Whether the type is an integer
@@ -344,11 +344,11 @@ enum ArBasicKind {
 #define GET_BPROP_PRIM_KIND_SU(_Props)                                         \
   ((_Props) & (BPROP_BOOLEAN | BPROP_INTEGER | BPROP_FLOATING | BPROP_UNSIGNED))

-#define IS_BPROP_PRIMITIVE(_Props) (((_Props)&BPROP_PRIMITIVE) != 0)
+#define IS_BPROP_PRIMITIVE(_Props) (((_Props) & BPROP_PRIMITIVE) != 0)

-#define IS_BPROP_BOOL(_Props) (((_Props)&BPROP_BOOLEAN) != 0)
+#define IS_BPROP_BOOL(_Props) (((_Props) & BPROP_BOOLEAN) != 0)

-#define IS_BPROP_FLOAT(_Props) (((_Props)&BPROP_FLOATING) != 0)
+#define IS_BPROP_FLOAT(_Props) (((_Props) & BPROP_FLOATING) != 0)

 #define IS_BPROP_SINT(_Props)                                                  \
   (((_Props) & (BPROP_INTEGER | BPROP_UNSIGNED | BPROP_BOOLEAN)) ==            \
@@ -361,20 +361,20 @@ enum ArBasicKind {
 #define IS_BPROP_AINT(_Props)                                                  \
   (((_Props) & (BPROP_INTEGER | BPROP_BOOLEAN)) == BPROP_INTEGER)

-#define IS_BPROP_STREAM(_Props) (((_Props)&BPROP_STREAM) != 0)
+#define IS_BPROP_STREAM(_Props) (((_Props) & BPROP_STREAM) != 0)

-#define IS_BPROP_SAMPLER(_Props) (((_Props)&BPROP_SAMPLER) != 0)
+#define IS_BPROP_SAMPLER(_Props) (((_Props) & BPROP_SAMPLER) != 0)

-#define IS_BPROP_TEXTURE(_Props) (((_Props)&BPROP_TEXTURE) != 0)
+#define IS_BPROP_TEXTURE(_Props) (((_Props) & BPROP_TEXTURE) != 0)

-#define IS_BPROP_OBJECT(_Props) (((_Props)&BPROP_OBJECT) != 0)
+#define IS_BPROP_OBJECT(_Props) (((_Props) & BPROP_OBJECT) != 0)

-#define IS_BPROP_MIN_PRECISION(_Props) (((_Props)&BPROP_MIN_PRECISION) != 0)
+#define IS_BPROP_MIN_PRECISION(_Props) (((_Props) & BPROP_MIN_PRECISION) != 0)

 #define IS_BPROP_UNSIGNABLE(_Props)                                            \
   (IS_BPROP_AINT(_Props) && GET_BPROP_BITS(_Props) != BPROP_BITS12)

-#define IS_BPROP_ENUM(_Props) (((_Props)&BPROP_ENUM) != 0)
+#define IS_BPROP_ENUM(_Props) (((_Props) & BPROP_ENUM) != 0)

 const UINT g_uBasicKindProps[] = {
     BPROP_PRIMITIVE | BPROP_BOOLEAN | BPROP_INTEGER | BPROP_NUMERIC |
@@ -3381,7 +3381,12 @@ class HLSLExternalSource : public ExternalSemaSource {
         paramTypes.push_back(context.UnsignedLongLongTy);
         break;
       case LICOMPTYPE_UINT:
-        paramTypes.push_back(context.UnsignedIntTy);
+        if (pArgs[i].uLegalTemplates == LITEMPLATE_VECTOR) {
+          paramTypes.push_back(LookupVectorType(
+              HLSLScalarType::HLSLScalarType_uint32, pArgs[i].uCols));
+        } else {
+          paramTypes.push_back(context.UnsignedIntTy);
+        }
         break;
       case LICOMPTYPE_VOID:
         paramTypes.push_back(context.VoidTy);
@@ -11168,8 +11173,7 @@ static void DiagnoseCalculateLOD(Sema &S, FunctionDecl *FD, SourceLocation Loc,

   if (!locallyVisited && !SM->IsSM68Plus()) {
     Diags.Report(Loc, diag::warn_hlsl_intrinsic_overload_in_wrong_shader_model)
-        << FD->getNameAsString() + " with SamplerComparisonState"
-        << "6.8";
+        << FD->getNameAsString() + " with SamplerComparisonState" << "6.8";
     return;
   }

diff --git a/utils/hct/gen_intrin_main.txt b/utils/hct/gen_intrin_main.txt
index 40b5f6d96a..7b4eee1b1f 100644
--- a/utils/hct/gen_intrin_main.txt
+++ b/utils/hct/gen_intrin_main.txt
@@ -389,6 +389,8 @@ namespace VkIntrinsics {
 u64 [[]] ReadClock(in uint scope);
 $funcT [[ro]] RawBufferLoad(in u64 addr);
 $funcT [[ro]] RawBufferLoad(in u64 addr, in uint alignment);
+$funcT [[ro]] RawBufferLoad2(in uint<2> addr);
+$funcT [[ro]] RawBufferLoad2(in uint<2> addr, in uint alignment);
 void [[]] RawBufferStore(in u64 addr, in $funcT value);
 void [[]] RawBufferStore(in u64 addr, in $funcT value, in uint alignment);
 void [[]] ext_execution_mode(in uint mode, ...);
